function notify(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}function log(text){const box=document.getElementById('messages'),d=document.createElement('div');d.className='message';d.textContent=text;box.prepend(d);while(box.children.length>5)box.lastChild.remove()}function updateUI(){document.getElementById('day').textContent=`Dia ${state.day}`;document.getElementById('clock').textContent=`${String(Math.floor(state.time)).padStart(2,'0')}:${String(Math.floor(state.minute/10)*10).padStart(2,'0')}`;document.getElementById('gold').textContent=state.gold;document.getElementById('seeds').textContent=state.seeds;document.getElementById('turnips').textContent=state.turnips;document.getElementById('weatherIcon').textContent=state.weather==='rain'?'🌧️':'☀️';document.getElementById('weather').textContent=state.weather==='rain'?'Chuva':'Primavera';document.getElementById('progress').style.width=`${Math.min(100,state.harvested/3*100)}%`;if(state.harvested>=3&&!state.goalDone){state.goalDone=true;state.gold+=60;log('🏆 Missão cumprida! Você ganhou 60 moedas.');notify('Missão concluída! +60 moedas 🌟');document.getElementById('questTitle').textContent='Uma nova vida no vale';document.getElementById('questText').textContent='Missão completa! Continue cuidando da sua fazenda e explore o vale.';document.getElementById('progress').style.width='100%'}document.querySelectorAll('.tool').forEach(b=>b.classList.toggle('active',b.dataset.tool===state.tool))}
function coords(e){let r=canvas.getBoundingClientRect(),s=T*scale;return{x:Math.floor((e.clientX-r.left-offsetX)/s),y:Math.floor((e.clientY-r.top-offsetY)/s)}}function dist(x,y){return Math.abs(state.player.x-x)+Math.abs(state.player.y-y)}function nearbyTarget(){let p=state.player;return props.find(o=>dist(o.x,o.y)<=1)}function act(x=state.player.x,y=state.player.y){let p=state.player;if(x==null){x=p.x+(p.dir==='left'?-1:p.dir==='right'?1:0);y=p.y+(p.dir==='up'?-1:p.dir==='down'?1:0)}if(x<0||y<0||x>=COLS||y>=ROWS)return;let prop=props.find(o=>dist(o.x,o.y)<=1&&o.x===x&&o.y===y)||props.find(o=>o.type==='sell'&&dist(o.x,o.y)<=1)||props.find(o=>o.type==='house'&&dist(o.x,o.y)<=2);if(prop?.type==='sell'){sell();return}if(prop?.type==='house'){sleep();return}if(prop?.type==='sign'){notify('Bem-vinda ao Vale das Flores! 🌼');return}
let k=key(x,y),c=state.crops[k];if(state.tool==='hoe'){if(c){notify('Este canteiro já está preparado.');return}if(tiles[k]==='blocked'||props.some(o=>o.x===x&&o.y===y)){notify('Não dá para cavar aqui.');return}if(!['farm','path'].includes(map[y*COLS+x]?.type)){notify('Procure o solo macio do canteiro.');return}state.crops[k]={stage:0,age:0};log('⛏️ Canteiro preparado! Agora plante uma semente.');}
else if(state.tool==='seeds'){if(!c){notify('Primeiro prepare a terra com a enxada.');return}if(c.stage>0){notify('Já tem algo crescendo aqui.');return}if(!state.seeds){notify('Sem sementes! Compre na lojinha.');return}state.seeds--;state.crops[k]={stage:1,age:0};state.planted++;log('🌱 Sementinha plantada! Regue todos os dias.');}
else if(state.tool==='water'){if(!c){notify('Regue uma plantinha para ela crescer!');return}if(state.watered[k]){notify('Já está bem hidratada!');return}state.watered[k]=true;c.age+=.5;if(c.stage===1)c.stage=2;log('💧 Plim! A plantinha adorou a água.');}
else if(state.tool==='hand'){if(c?.stage>=3){delete state.crops[k];delete state.watered[k];state.turnips++;state.harvested++;log('🥕 Nabinho colhido! Leve à caixa azul para vender.');notify('Colheita fresquinha! +1 nabo');}else if(c){notify(c.stage===0?'Plante uma semente primeiro!':'Ainda está crescendo. Regue para ajudar!')}else{let nearby=props.find(o=>o.type==='flower'&&dist(o.x,o.y)<=1);if(nearby)notify('Que flor cheirosa! 🌼');else notify('Nada para pegar por aqui.')}}updateUI();draw()}
function sell(){if(state.turnips<1){notify('Você ainda não tem nabos para vender.');return}let n=state.turnips,earn=n*25;state.turnips=0;state.gold+=earn;updateUI();log(`🪙 Vendeu ${n} nabo${n>1?'s':''} por ${earn} moedas!`);notify(`Venda feita! +${earn} moedas 🪙`)}
function sleep(){if(state.time<17){notify('Ainda é cedo! Explore e cuide da plantação.');return}state.day++;state.time=7;state.minute=0;let rain=Math.random()<.25;state.weather=rain?'rain':'sun';for(const k in state.crops){let c=state.crops[k];if(c.stage>0){if(state.watered[k]||rain)c.stage=Math.min(3,c.stage+1);c.age++;}}state.watered={};if(state.day%3===0){state.seeds+=2;log('📦 Entrega da fazenda: +2 sementes grátis!')}state.player.x=12;state.player.y=11;updateUI();log(`🌅 Dia ${state.day}! ${rain?'Está chovendo — suas plantas foram regadas.':'Um novo dia ensolarado começa.'}`);notify(`Dia ${state.day} — ${rain?'chuvoso':'ensolarado'} 🌿`);draw()}
function setTool(t){state.tool=t;document.querySelectorAll('.tool').forEach(b=>b.classList.toggle('active',b.dataset.tool===t));let names={hoe:'Enxada',seeds:'Sementes',water:'Regador',hand:'Mão'};notify(`${names[t]} selecionada`)}document.querySelectorAll('.tool').forEach(b=>b.addEventListener('click',()=>setTool(b.dataset.tool)));
function modal(title,body,buttons){overlayOpen=true;let el=document.getElementById('modal');el.innerHTML=`<div class="big">${title==='Bem-vinda!'?'🌼':title.includes('Lojinha')?'🧺':title.includes('Pausa')?'🌿':'🌙'}</div><h2>${title}</h2><p>${body}</p><div class="modal-actions">${buttons.map(([label,action,cls='action'])=>`<button class="${cls}" data-action="${action}">${label}</button>`).join('')}</div>`;document.getElementById('overlay').classList.add('show');el.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{let a=b.dataset.action;if(a==='start'){document.getElementById('overlay').classList.remove('show');overlayOpen=false;notify('Sua jornada começa agora! 🌱')}if(a==='seed'){if(state.gold>=15){state.gold-=15;state.seeds+=3;notify('Comprou 3 sementes por 15 moedas! 🌱');updateUI()}else notify('Você precisa de mais moedas!')}if(a==='close'){document.getElementById('overlay').classList.remove('show');overlayOpen=false}if(a==='sleep'){document.getElementById('overlay').classList.remove('show');overlayOpen=false;state.time=18;sleep()}})}
function welcome(){modal('Bem-vinda!','Este vale é todo seu. Prepare a terra, plante sementes e regue suas plantinhas. Colha 3 nabos para completar sua primeira missão!<br><br><b>Dica:</b> sua fazenda fica no canteiro marrom à esquerda. A caixa azul vende suas colheitas.',[['Começar a jogar','start']])}function openShop(){modal('Lojinha da vila','Uma vizinha deixou sementes fresquinhas para você. Cada pacote tem 3 sementes e custa 15 moedas.',[['Comprar sementes · 15 🪙','seed'],['Agora não','close','action secondary']])}document.getElementById('overlay').addEventListener('click',e=>{if(e.target.id==='overlay'){e.currentTarget.classList.remove('show');overlayOpen=false}});

const held={};let moveCooldown=0;function canMove(x,y){return x>=0&&y>=0&&x<COLS&&y<ROWS&&!tiles[key(x,y)]&&!props.some(o=>o.x===x&&o.y===y&&['tree','pond'].includes(o.type))}function move(dx,dy){if(overlayOpen)return;let p=state.player,nx=p.x+dx,ny=p.y+dy;p.dir=dx<0?'left':dx>0?'right':dy<0?'up':'down';if(canMove(nx,ny)){p.x=nx;p.y=ny;p.walk+=1}let prop=props.find(o=>o.x===nx&&o.y===ny);if(prop?.type==='sell'){notify('Caixa de vendas: pressione Espaço para vender!')}if(prop?.type==='house'){notify('Sua casinha aconchegante. Espaço para dormir.')}draw()}
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(overlayOpen){if(e.key==='Escape'){document.getElementById('overlay').classList.remove('show');overlayOpen=false}return}let k=e.key.toLowerCase();if(k==='1')setTool('hoe');if(k==='2')setTool('seeds');if(k==='3')setTool('water');if(k==='4')setTool('hand');if(k===' '||k==='enter'){act();return}if(k==='e'){let prop=nearbyTarget();if(prop?.type==='sell')sell();else if(prop?.type==='house')sleep();else if(prop?.type==='sign')notify('Bem-vinda ao Vale das Flores! 🌼');else openShop();return}if(k==='escape'){modal('Pausa','Seu vale está salvo enquanto esta página estiver aberta.',[['Continuar','close'],['Dormir','sleep','action secondary']]);return}const dirs={arrowup:[0,-1],w:[0,-1],arrowdown:[0,1],s:[0,1],arrowleft:[-1,0],a:[-1,0],arrowright:[1,0],d:[1,0]};if(dirs[k]&&!held[k]){held[k]=true;move(...dirs[k])}});window.addEventListener('keyup',e=>{held[e.key.toLowerCase()]=false});
canvas.addEventListener('pointerdown',e=>{if(overlayOpen)return;canvas.setPointerCapture(e.pointerId);const {x,y}=coords(e);if(x<0||y<0||x>=COLS||y>=ROWS)return;let targetProp=props.find(o=>o.x===x&&o.y===y);if(targetProp?.type==='sell'){state.player.x=17;state.player.y=11;state.player.dir='right';sell();draw();return}if(targetProp?.type==='house'){if(state.time>=17)sleep();else notify('Sua casinha. Volte depois das 17h para dormir.');return}if(targetProp?.type==='sign'){notify('Bem-vinda ao Vale das Flores! 🌼');return}let md=Math.abs(x-state.player.x)+Math.abs(y-state.player.y);if(md<=1){state.player.dir=x<state.player.x?'left':x>state.player.x?'right':y<state.player.y?'up':'down';act(x,y)}else if(md<=5){let dx=Math.sign(x-state.player.x),dy=Math.sign(y-state.player.y);if(Math.abs(x-state.player.x)>Math.abs(y-state.player.y)){move(dx,0);if(state.player.x!==x)move(0,dy)}else{move(0,dy);if(state.player.y!==y)move(dx,0)}setTimeout(()=>{if(Math.abs(x-state.player.x)+Math.abs(y-state.player.y)<=1)act(x,y)},60)}else{notify('Chegue mais perto! Use WASD para andar.')}});
let touchStart=null;canvas.addEventListener('touchstart',e=>{if(e.touches.length===1){touchStart={x:e.touches[0].clientX,y:e.touches[0].clientY,time:Date.now()}}},{passive:true});canvas.addEventListener('touchend',e=>{if(!touchStart)return;let t=e.changedTouches[0],dx=t.clientX-touchStart.x,dy=t.clientY-touchStart.y;touchStart=null;if(Math.max(Math.abs(dx),Math.abs(dy))>24){move(Math.abs(dx)>Math.abs(dy)?Math.sign(dx):0,Math.abs(dy)>=Math.abs(dx)?Math.sign(dy):0)}},{passive:true});document.getElementById('sound').onclick=e=>{state.sound=!state.sound;e.currentTarget.textContent=state.sound?'♫':'♪';notify(state.sound?'Sons ativados!':'Sons desativados')};
function tick(now){let dt=Math.min(.1,(now-last)/1000||0);last=now;if(!overlayOpen){state.minute+=dt*3.1;if(state.minute>=60){state.minute-=60;state.time++;if(state.time>=24){state.time=24;}}if(state.time>=24){state.time=24;state.minute=0}updateUI()}requestAnimationFrame(tick)}
function init(){resize();updateUI();welcome();requestAnimationFrame(tick);let r=canvas.getBoundingClientRect();if(r.width<500)document.getElementById('footerHint').textContent='Toque para agir · Deslize para andar';}init();
})();
</script></body></html>
